Engine Class: Has a start() method to simulate starting the engine.Car Class: Receives an Engine via its constructor; drive() uses the injected Engine.Main Method: Creates an Engine instance, injects it into Car through the constructor, then calls car.drive().2. Setter InjectionSetter Injection involves providing the dependency via a setter method after the object is created. This approach is more flexible than constructor injection because it allows dependencies to be set or changed after object creation.
            C++

    #include <iostream>

class Engine {
public:
    void start() {
        std::cout << "Engine started" << std::endl;
    }
};

class Car {
private:
    Engine* engine;  // Declaring a dependency on Engine

public:
    // No constructor injection here. Using setter to inject dependency
    void setEngine(Engine* engine) {
        this->engine = engine;  // Injecting dependency via setter method
    }

    void drive() {
        engine->start();  // Using the injected Engine dependency
        std::cout << "Car is driving" << std::endl;
    }
};

int main() {
    Engine engine;  // Create Engine object (dependency)

    // Create a Car object without providing the Engine immediately
    Car car;

    // Inject the Engine dependency using the setter method
    car.setEngine(&engine);  // Set the dependency via the setter method
    car.drive();  // Call the drive method to use the Engine
    return 0;
}


